const results = await Promise.allSettled([
  tools.view_image({path:"/app/runs/seurat_bathers/canvas_cam.png",detail:"high"}),
  tools.exec_command({cmd:"cat /app/runs/seurat_bathers/summary.json && tail -n 3 /app/output/run_log.jsonl && ls -lh /app/output/gen.py /app/output/planned_strokes.json /app/runs/seurat_bathers",yield_time_ms:10000,max_output_tokens:1500})
]);
for (const r of results) {
  if (r.status === "fulfilled") {
    const v = r.value;
    if (v.image_url) image(v.image_url);
    else text(v.output);
  } else text(String(r.reason));
}

